```powershell
Get-MyNamespaceMyCollectionServiceAuthSpec {
    @{
        options = @{
            my_service_url = @{ type = 'str'; required = $true }
            my_service_username = @{ type = 'str' }
            my_service_password = @{ type = 'str'; no_log = $true }
        }
        required_together = @(,@('my_service_username', 'my_service_password'))
    }
}
Export-ModuleMember -Function 'Get-MyNamespaceMyCollectionServiceAuthSpec', 'Invoke-MyServiceResource'
```
`Invoke-MyServiceResource` reads `$Module.Params.my_service_*` to act on the resource.
